import os,tempfile,pathlib,stat

def atomic_write(target,content,mode=None):
    target=pathlib.Path(target).absolute()
    if not isinstance(content,bytes):raise ValueError('content must be bytes')
    if target.is_symlink():raise ValueError('refuse symlink target')
    if not target.parent.is_dir():raise ValueError('target directory must exist')
    if target.exists() and not target.is_file():raise ValueError('target must be a regular file')
    if mode is not None and (isinstance(mode,bool) or not isinstance(mode,int) or mode<0 or mode>0o777):raise ValueError('invalid mode')
    chosen=mode if mode is not None else (stat.S_IMODE(target.stat().st_mode) if target.exists() else 0o600)
    fd,name=tempfile.mkstemp(prefix='.'+target.name+'.',suffix='.tmp',dir=target.parent)
    temp=pathlib.Path(name);replaced=False
    try:
        with os.fdopen(fd,'wb') as stream:
            stream.write(content);stream.flush();os.fsync(stream.fileno())
        os.chmod(temp,chosen)
        os.replace(temp,target);replaced=True
        dirfd=os.open(target.parent,os.O_RDONLY|getattr(os,'O_DIRECTORY',0))
        try:os.fsync(dirfd)
        finally:os.close(dirfd)
        return {'bytes':len(content),'mode':chosen,'replaced':True}
    finally:
        if not replaced:
            try:temp.unlink()
            except FileNotFoundError:pass
